// FAIL CLOSED HMAC — deploy/n8n/HMAC.md
// NEVER use JSON.stringify(parsedBody) as a raw-body substitute.
const crypto = require('crypto');

function reject(reason) {
  return [{ json: { verified: false, error: reason } }];
}

const secret = $env.LAPTOP_MONITOR_WEBHOOK_SECRET;
if (!secret) return reject('missing_secret');

const item = $input.first();
const headers = (item.json && item.json.headers) ? item.json.headers : {};
const ts = headers['x-laptop-monitor-timestamp'] || headers['X-Laptop-Monitor-Timestamp'];
const sig = headers['x-laptop-monitor-signature'] || headers['X-Laptop-Monitor-Signature'];
if (!ts) return reject('missing_timestamp');
if (!sig) return reject('missing_signature');
if (!item.binary || !item.binary.data) return reject('missing_raw_body');

let raw;
try {
  raw = await this.helpers.getBinaryDataBuffer(0, 'data');
} catch (e) {
  return reject('missing_raw_body');
}
if (!raw || !Buffer.isBuffer(raw) || raw.length === 0) return reject('missing_raw_body');

const tsNum = Number(ts);
if (!Number.isFinite(tsNum)) return reject('bad_timestamp');
const skew = Math.abs(Math.floor(Date.now() / 1000) - Math.floor(tsNum));
if (skew > 300) return reject('timestamp_skew');

const expected = crypto
  .createHmac('sha256', secret)
  .update(Buffer.concat([
    Buffer.from(String(ts), 'utf8'),
    Buffer.from('.', 'utf8'),
    raw,
  ]))
  .digest('hex');

const a = Buffer.from(expected, 'utf8');
const b = Buffer.from(String(sig), 'utf8');
if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) {
  return reject('bad_signature');
}

let payload;
try {
  payload = JSON.parse(raw.toString('utf8'));
} catch (e) {
  return reject('invalid_json');
}

return [{
  json: {
    verified: true,
    event: payload.event,
    status: payload.status,
    app_version: payload.app_version,
    instance_id: payload.instance_id,
    run_id: payload.run_id,
    started_at: payload.started_at,
    finished_at: payload.finished_at,
    error_summary: payload.error_summary,
    alerts_created: payload.alerts_created,
    messages_sent: payload.messages_sent,
    messages_failed: payload.messages_failed,
    stores: payload.stores,
    top_deals: payload.top_deals,
  },
}];

// Failure Alert — only after HMAC OK + status partial/failed
// Dedupe key: run_id (workflow static data). Telegram via env (not workflow JSON).
const item = $input.first().json || {};
const status = String(item.status || '').toLowerCase();

function safeSummary(text, limit = 160) {
  if (text === undefined || text === null || text === '') return null;
  let cleaned = String(text).replace(/\s+/g, ' ').trim();
  const lower = cleaned.toLowerCase();
  if (lower.includes('api.telegram.org/bot') || lower.includes('bot_token') || lower.includes('webhook_secret')) {
    const head = String(text).split(':', 1)[0].trim();
    cleaned = head && !head.includes(' ') && head.length < 80 ? head : 'error redacted';
  }
  if (cleaned.length > limit) cleaned = cleaned.slice(0, limit - 1).trimEnd() + '…';
  return cleaned || null;
}

function formatMsk(iso) {
  if (!iso) return '—';
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return String(iso);
  const fmt = new Intl.DateTimeFormat('en-GB', {
    timeZone: 'Europe/Moscow',
    year: 'numeric', month: '2-digit', day: '2-digit',
    hour: '2-digit', minute: '2-digit', second: '2-digit',
    hour12: false,
  });
  const parts = Object.fromEntries(fmt.formatToParts(d).filter(p => p.type !== 'literal').map(p => [p.type, p.value]));
  return `${parts.year}-${parts.month}-${parts.day} ${parts.hour}:${parts.minute}:${parts.second} MSK`;
}

function buildMessage(payload) {
  const st = String(payload.status || '').toLowerCase();
  if (st !== 'partial' && st !== 'failed') return null;
  const timeTxt = formatMsk(payload.finished_at || payload.started_at);
  const instance = String(payload.instance_id || 'unknown');
  const runId = payload.run_id;
  const stores = Array.isArray(payload.stores) ? payload.stores : [];
  const problem = [];
  const working = [];
  for (const store of stores) {
    const name = String(store.display_name || store.slug || 'store');
    const sst = String(store.status || '').toLowerCase();
    if (sst === 'ok' || sst === 'success') working.push(`• ${name} — OK`);
    else {
      const reason = safeSummary(store.error) || sst || 'failed';
      problem.push(`• ${name} — FAILED: ${reason}`);
    }
  }
  if (st === 'partial') {
    return [
      '⚠️ Laptop Monitor — PARTIAL', '',
      `Время: ${timeTxt}`,
      `Instance: ${instance}`,
      `Run: ${runId}`, '',
      'Проблемные магазины:',
      ...(problem.length ? problem : ['• (не указаны)']), '',
      'Работают:',
      ...(working.length ? working : ['• (нет)']), '',
      'Telegram:',
      `sent: ${payload.messages_sent ?? '—'}`,
      `failed: ${payload.messages_failed ?? '—'}`,
    ].join('\n');
  }
  const summary = safeSummary(payload.error_summary) || 'pipeline failed';
  const storeLines = stores.length
    ? stores.map((store) => {
        const name = String(store.display_name || store.slug || 'store');
        const sst = String(store.status || 'unknown').toUpperCase();
        const err = safeSummary(store.error);
        return `• ${name} — ${sst}` + (err ? `: ${err}` : '');
      })
    : ['• (нет данных)'];
  return [
    '🔴 Laptop Monitor — FAILED', '',
    `Время: ${timeTxt}`,
    `Instance: ${instance}`,
    `Run: ${runId}`, '',
    'Причина:', summary, '',
    'Stores:', ...storeLines,
  ].join('\n');
}

if (status !== 'partial' && status !== 'failed') {
  return [{ json: { ...item, failure_alert: 'skipped_not_failure' } }];
}

const staticData = $getWorkflowStaticData('global');
staticData.lmFailureAlerts = staticData.lmFailureAlerts || {};
const runKey = String(item.run_id ?? '');
if (runKey && staticData.lmFailureAlerts[runKey]) {
  return [{ json: { ...item, failure_alert: 'deduped' } }];
}

const text = buildMessage(item);
if (!text) {
  return [{ json: { ...item, failure_alert: 'skipped_not_failure' } }];
}

const token = $env.LAPTOP_MONITOR_TELEGRAM_BOT_TOKEN;
const chatRaw = $env.LAPTOP_MONITOR_TELEGRAM_CHAT_ID || '';
const chatId = String(chatRaw).split(',')[0].trim();
if (!token || !chatId) {
  return [{ json: { ...item, failure_alert: 'telegram_env_missing' } }];
}

try {
  const resp = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://api.telegram.org/bot' + token + '/sendMessage',
    headers: { 'content-type': 'application/json' },
    body: {
      chat_id: chatId,
      text,
      disable_web_page_preview: true,
    },
    json: true,
    timeout: 10000,
  });
  if (!resp || resp.ok !== true) {
    return [{ json: { ...item, failure_alert: 'telegram_rejected' } }];
  }
} catch (e) {
  return [{ json: { ...item, failure_alert: 'telegram_error' } }];
}

if (runKey) {
  staticData.lmFailureAlerts[runKey] = Date.now();
  const keys = Object.keys(staticData.lmFailureAlerts);
  if (keys.length > 200) {
    keys.sort((a, b) => staticData.lmFailureAlerts[a] - staticData.lmFailureAlerts[b]);
    for (const k of keys.slice(0, keys.length - 200)) delete staticData.lmFailureAlerts[k];
  }
}

return [{ json: { ...item, failure_alert: 'sent' } }];
